"""Eight original four-beat causal stories for ASTRA Shorts."""
PLOTS = [
("heron-bridge-counterweight","The Heron and the Broken Bridge","river rescue",[("THE BRIDGE DROPPED","A heron discovered that the village footbridge sagged whenever the morning delivery cart reached its center.","forest","DANGER"),("THE WRONG FIX","She tied the loose rail to a tree, but the bridge deck still tilted under an empty basket.","door","FAILED"),("THE HIDDEN WEIGHT","Beneath the planks, she found a counterweight rope trapped around a fallen branch instead of its pulley.","clock","DISCOVERY"),("THE SAFE CROSSING","The heron freed the rope from shore, tested the empty bridge, and reopened it only after the counterweight balanced.","forest","RESTORED")]),
("mole-bakery-chimney","The Mole and the Silent Bakery","village mystery",[("NO BREAD TODAY","A mole found the bakery oven cold just before the town's annual harvest breakfast was supposed to begin.","book","PROBLEM"),("A SMOKY ATTEMPT","He piled on extra firewood, but smoke spilled through the bakery door and forced everyone outside.","door","SETBACK"),("THE BLOCKED FLUE","From the roof ladder, the mole noticed a loose metal cap had slipped sideways over the chimney opening.","clock","CLUE"),("BREAKFAST SAVED","After the oven cooled, the baker secured the cap, checked the draft, and baked the morning loaves safely.","book","SOLUTION")]),
("otter-ferry-bell","The Otter and the Missing Ferry Bell","harbor mystery",[("THE FERRY WAITED","An otter saw travelers waiting at the dock because the ferry bell had stopped ringing across the misty channel.","ship","DELAY"),("THE FAILED SIGNAL","She waved a bright flag, but the fog swallowed the signal before the captain could see it.","signal","SETBACK"),("A SOUND BELOW","The otter heard a faint clink under the pier and found the bell's clapper tangled in a fishing net.","ship","DISCOVERY"),("THE CROSSING RESUMED","She untangled the clapper, tested the bell from the dock, and the captain answered before approaching slowly.","signal","SUCCESS")]),
("badger-library-flood","The Badger and the Floating Library","library rescue",[("WATER AT THE DOOR","A badger discovered rainwater creeping under the library entrance toward shelves of handwritten village records.","book","ALARM"),("THE FIRST BARRIER","He stacked books against the door, but water soaked the bottom volumes and continued spreading across the floor.","door","MISTAKE"),("THE REAL SOURCE","Following a thin stream uphill, he found a blocked drain diverting the courtyard runoff toward the library.","forest","CLUE"),("THE RECORDS SURVIVED","The badger moved the books onto tables, cleared the drain with helpers, and dried the rescued records carefully.","book","RESCUED")]),
("fox-observatory-shutter","The Fox and the Stuck Observatory","observatory repair",[("THE SKY DISAPPEARED","A fox arrived for the meteor shower and found the observatory roof shutter jammed halfway across the telescope.","planet","PROBLEM"),("A RISKY PULL","He tugged the shutter chain harder, but its wheel slipped and rattled against the wooden track.","clock","SETBACK"),("A SMALL OBSTRUCTION","With the telescope covered, he spotted a fallen bolt wedged beneath the track's smallest guide wheel.","robot","DISCOVERY"),("THE STARS RETURNED","The fox removed the bolt with a magnet, replaced its missing fastener, and opened the shutter smoothly.","planet","RESOLVED")]),
("rabbit-garden-waterwheel","The Rabbit and the Quiet Waterwheel","garden repair",[("THE GARDEN DRIED","A rabbit noticed the garden channels empty even though the stream beside the old waterwheel was flowing strongly.","forest","TROUBLE"),("PUSHING DID NOTHING","She pushed the wheel with a long pole, but it turned once and stopped before filling the irrigation trough.","door","SETBACK"),("THE HIDDEN JAM","She traced the axle and discovered a loose wooden peg pressing against the wheel's support bracket.","clock","CLUE"),("WATER FLOWED AGAIN","The rabbit reset the peg with the gardener, tested the wheel from a safe distance, and watered the seedlings.","forest","RECOVERY")]),
("squirrel-clocktower-rope","The Squirrel and the Late Clock","town mystery",[("THE CLOCK FROZE","A squirrel realized the clocktower hands had stopped just before the village's morning train was due.","clock","ALARM"),("A FALSE RESET","He moved the hands forward, but the clock stopped again before its first bell could ring.","signal","FAILED"),("THE MISSING TENSION","Inside the tower, he discovered that the hanging drive weight rested on a shelf after its rope slipped sideways.","clock","CLUE"),("THE TIME RETURNED","The clockmaker rehung the weight and aligned the rope, then checked the bell against the station clock.","signal","RESTORED")]),
("penguin-snow-marker","The Penguin and the Buried Trail","snowfield rescue",[("THE PATH VANISHED","A penguin found the rescue team's trail markers buried after fresh snow covered the route to a hillside shelter.","forest","LOST"),("THE WRONG DIRECTION","He followed old footprints, but they ended beside a frozen pond far from the shelter's entrance.","door","SETBACK"),("THE WINDWARD CLUE","The penguin noticed one marker's red ribbon sticking out on the windward side of a snowdrift.","signal","DISCOVERY"),("A SAFER ROUTE","He uncovered each marker without crossing the pond and guided the team along the marked ridge to shelter.","forest","SAFE")])
]
